function randomNonce(bytes: number): string {
  const binary = Array.from(crypto.getRandomValues(new Uint8Array(bytes)), (byte) => String.fromCharCode(byte)).join("");
  return btoa(binary).replaceAll("+", "-").replaceAll("/", "_").replace(/=+$/u, "");
}

function runtimeBoundaryCopy(boundary: PlatformTrustBoundary): string {
  if (!boundary.hostingProfile) {
    return "Provider placement is opt-in. Selected projects stay pinned to one stateful runner and publish only an exact observed generation; remote backups require a separate provider transport.";
  }
  const signup = boundary.signupMode === "public"
    ? "Public signup is enabled."
    : boundary.signupMode === "disabled"
      ? "Account signup is disabled."
      : "Bootstrap and invitation-controlled onboarding are configured.";
  if (boundary.hostingProfile === "trusted") {
    return `Trusted local runtime · Local apps use the ${boundary.runnerKind} runner and share the control-plane Unix trust boundary. ${signup}${
      boundary.signupMode === "public"
        ? " Stop public onboarding until isolated hosting is configured."
        : " Only accept deployers whose code the host operator trusts."
    }`;
  }
  return `Isolated local runtime · Local apps use the ${boundary.runnerKind} runner instead of the control-plane process boundary. ${signup} Keep the runtime image pinned and verify the container boundary before public hosting.`;
}

function initialAuthMode(pathname: string): PlatformConsoleAuthMode {
  if (pathname === "/signup") return "signup";
  if (pathname === "/invite") return "invite";
  return "login";
}

function initialConsoleView(
  pathname: string,
  platformAdmin: boolean,
  billingEnabled: boolean,
): PlatformConsoleView {
  if (pathname === "/invite") return "workspace";
  if (pathname === "/usage") return "usage";
  if (pathname === "/billing" && billingEnabled) return "billing";
  if (pathname === "/activity") return "activity";
  if (pathname === "/admin") return platformAdmin ? "admin" : "overview";
  if (pathname === "/workspaces" || pathname.startsWith("/workspaces/")) return "workspace";
  if (pathname.startsWith("/projects/")) return "project";
  return "overview";
}

function viewLabel(view: PlatformConsoleView): string {
  if (view === "usage") return "Usage";
  if (view === "billing") return "Plans and billing";
  if (view === "activity") return "Activity";
  if (view === "admin") return "Control plane";
  if (view === "workspace") return "People";
  if (view === "project") return "Project";
  return "Overview";
}

function initials(value: string): string {
  return value
    .split("@", 1)[0]!
    .split(/[ ._-]+/u)
    .map((part) => part[0] ?? "")
    .join("")
    .slice(0, 2)
    .toUpperCase() || "C";
}

function escapeHtml(value: string): string {
  return value
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}
